package com.bbmurloc.victoriaeconomics.server.storage.sqlite;

import java.util.List;

/** v8 time/finance/accrual foundation; payment linkage is defined alongside it. No production issuance API. */
final class EconomyFinancialSchema {
    private EconomyFinancialSchema() {}
    static final List<String> DDL = List.of(
            "CREATE TABLE economic_time(id INTEGER PRIMARY KEY CHECK(id=1), accepted_tick INTEGER NOT NULL CHECK(typeof(accepted_tick)='integer' AND accepted_tick>=0),production_callback_returned_tick INTEGER NOT NULL CHECK(typeof(production_callback_returned_tick)='integer' AND production_callback_returned_tick>=0),first_uncertain_production_tick INTEGER CHECK(first_uncertain_production_tick IS NULL OR (typeof(first_uncertain_production_tick)='integer' AND first_uncertain_production_tick>0 AND first_uncertain_production_tick<=accepted_tick)),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0),CHECK(production_callback_returned_tick<=accepted_tick))",
            "CREATE TABLE payroll_runtime(id INTEGER PRIMARY KEY CHECK(id=1), authority TEXT NOT NULL CHECK(authority='BUILDING_STAFFING'), processed_tick INTEGER NOT NULL CHECK(typeof(processed_tick)='integer' AND processed_tick>=0), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0))",
            "CREATE TABLE currencies(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL CHECK(length(trim(name))>0))",
            "CREATE TABLE finance_accounts(id TEXT PRIMARY KEY NOT NULL, company_id TEXT REFERENCES companies(id), region_id TEXT REFERENCES regions(id), currency_id TEXT NOT NULL REFERENCES currencies(id), balance INTEGER NOT NULL CHECK(typeof(balance)='integer' AND balance>=0), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0), CHECK((company_id IS NOT NULL AND region_id IS NULL) OR (company_id IS NULL AND region_id IS NOT NULL)), UNIQUE(company_id,currency_id), UNIQUE(region_id,currency_id))",
            "CREATE TABLE finance_events(id TEXT PRIMARY KEY NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('OPEN','TRANSFER','EXTERNAL_CREDIT')), source_account TEXT REFERENCES finance_accounts(id), target_account TEXT NOT NULL REFERENCES finance_accounts(id), currency_id TEXT NOT NULL REFERENCES currencies(id), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>=0), provenance TEXT NOT NULL CHECK(length(trim(provenance))>0), CHECK((kind='OPEN' AND source_account IS NULL AND amount=0) OR (kind='EXTERNAL_CREDIT' AND source_account IS NULL AND amount>0) OR (kind='TRANSFER' AND source_account IS NOT NULL AND source_account<>target_account AND amount>0)))",
            "CREATE TABLE finance_ledger(sequence INTEGER PRIMARY KEY, event_id TEXT NOT NULL REFERENCES finance_events(id), line INTEGER NOT NULL CHECK(typeof(line)='integer' AND line>=0), account_id TEXT NOT NULL REFERENCES finance_accounts(id), delta INTEGER NOT NULL CHECK(typeof(delta)='integer'), balance_after INTEGER NOT NULL CHECK(typeof(balance_after)='integer' AND balance_after>=0), UNIQUE(event_id,line))",
            "CREATE TABLE cash_reservations(id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL REFERENCES finance_accounts(id), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0), purpose TEXT NOT NULL CHECK(length(trim(purpose))>0), active INTEGER NOT NULL CHECK(active IN (0,1)))",
            "CREATE TABLE regional_wage_rates(region_id TEXT NOT NULL REFERENCES regions(id), currency_id TEXT NOT NULL REFERENCES currencies(id), effective_tick INTEGER NOT NULL CHECK(typeof(effective_tick)='integer' AND effective_tick>=0), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>=0), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0), PRIMARY KEY(region_id,effective_tick), UNIQUE(region_id,revision))",
            "CREATE TABLE payroll_accruals(id TEXT PRIMARY KEY NOT NULL, building_id TEXT NOT NULL REFERENCES economic_buildings(id), company_id TEXT NOT NULL REFERENCES companies(id), region_id TEXT NOT NULL REFERENCES regions(id), currency_id TEXT NOT NULL REFERENCES currencies(id), start_tick INTEGER NOT NULL CHECK(typeof(start_tick)='integer' AND start_tick>=0), last_accrued_tick INTEGER NOT NULL CHECK(typeof(last_accrued_tick)='integer' AND last_accrued_tick>=0), closed_tick INTEGER CHECK(closed_tick IS NULL OR (typeof(closed_tick)='integer' AND closed_tick>=start_tick AND closed_tick<=last_accrued_tick)), employees INTEGER NOT NULL CHECK(typeof(employees)='integer' AND employees>=0), accrued INTEGER NOT NULL CHECK(typeof(accrued)='integer' AND accrued>=0), unmatured INTEGER NOT NULL CHECK(typeof(unmatured)='integer' AND unmatured>=0), matured INTEGER NOT NULL CHECK(typeof(matured)='integer' AND matured>=0), paid INTEGER NOT NULL CHECK(typeof(paid)='integer' AND paid>=0), remainder INTEGER NOT NULL CHECK(typeof(remainder)='integer' AND remainder>=0 AND remainder<1200), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0), CHECK(last_accrued_tick>=start_tick AND matured<=accrued AND unmatured=accrued-matured AND paid<=matured))",
            "CREATE TABLE payroll_employment_history(segment_id TEXT NOT NULL REFERENCES payroll_accruals(id), effective_tick INTEGER NOT NULL CHECK(typeof(effective_tick)='integer' AND effective_tick>=0), employees INTEGER NOT NULL CHECK(typeof(employees)='integer' AND employees>=0), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0), PRIMARY KEY(segment_id,revision))",
            "CREATE UNIQUE INDEX one_open_payroll_segment_per_building ON payroll_accruals(building_id) WHERE closed_tick IS NULL",
            "CREATE TABLE payroll_liabilities(segment_id TEXT NOT NULL REFERENCES payroll_accruals(id), period_id INTEGER NOT NULL CHECK(typeof(period_id)='integer' AND period_id>0), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>=0), paid INTEGER NOT NULL CHECK(typeof(paid)='integer' AND paid>=0), CHECK(paid<=amount), PRIMARY KEY(segment_id,period_id))");
}
